function ccEmotionChromaColor() {
    return (ccSettings && ccSettings.emotionsChromaKey === '#ff00ff') ? '#ff00ff' : '#00ff00';
}

function ccClampChromaNumber(value, min, max, fallback) {
    value = Number(value);
    if (!isFinite(value)) value = fallback;
    return Math.max(min, Math.min(max, value));
}

/* One normalized source for both the ComfyUI node and Review controls. New
   installs favour border sampling because diffusion models commonly produce a
   shaded approximation of #00ff00 rather than a perfectly flat RGB fill. */
function ccEmotionChromaSettings() {
    var mode = ccSettings && ccSettings.emotionsChromaMode;
    if (mode !== 'manual' && mode !== 'auto_corners') mode = 'auto_border';
    var low = ccClampChromaNumber(ccSettings && ccSettings.emotionsChromaTransparent, 0, 254, 36);
    var high = ccClampChromaNumber(ccSettings && ccSettings.emotionsChromaOpaque, 1, 255, 145);
    if (low >= high) high = Math.min(255, low + 1);
    return {
        key_mode: mode,
        key_color: ccEmotionChromaColor(),
        soft_matte: !ccSettings || ccSettings.emotionsChromaSoft !== false,
        transparent_threshold: low,
        opaque_threshold: high,
        tolerance: ccClampChromaNumber(ccSettings && ccSettings.emotionsChromaTolerance, 0, 255, 32),
        despill: !ccSettings || ccSettings.emotionsChromaDespill !== false,
        edge_contract: Math.round(ccClampChromaNumber(ccSettings && ccSettings.emotionsChromaContract, 0, 16, 1)),
        edge_feather: ccClampChromaNumber(ccSettings && ccSettings.emotionsChromaFeather, 0, 16, 0.35)
    };
}

function ccEmotionChromaPromptBlock(color) {
    return 'Place the entire character on a perfectly flat solid ' + color + ' chroma-key background for background removal.\n' +
        'The background must be one uniform color with no shadows, gradients, texture, reflections, floor plane, scenery, or lighting variation.\n' +
        'Keep the full body completely inside the frame with crisp edges and generous padding.\n\n' +
        'No cast shadow, contact shadow, reflection, text, or watermark.';
}

