var CC_NAR_FIELD_RULES =
    'FIELD RULES:\n' +
    '- These are attributes of a NARRATIVE VOICE, never of a person or a place.\n' +
    '- narScope: Solo GM (runs the world for a lone {{user}}), Group narrator (muted camera among other cards), or Universal.\n' +
    '- If you set narSceneHeader to anything except Off, first_mes and every {{char}} reply in mes_example must OPEN with the \ud83d\udccd header line — but NEVER write it as a rule in description or personality.\n' +
    '- narDuties: what the narrator is allowed to do unprompted (voice NPCs, skip time, introduce events, shift weather…) — 1-2 sentences.\n' +
    '- narGenre: the setting frame it defaults to, if any.\n' +
    '- Keep other values SHORT — a word or a brief phrase.\n' +
    '- Leave a field empty ("") only when it genuinely does not apply.\n\n';

/* Shared rules for the location attribute fields. */
var CC_LOC_FIELD_RULES =
    'FIELD RULES:\n' +
    '- These are attributes of a PLACE, never of a person.\n' +
    '- Keep values SHORT — a word or a brief phrase. Exceptions: layout, landmarks, secrets, events, rumors may be 1-2 sentences.\n' +
    '- narForbidden: things the narrator must never do in this specific place (a brief phrase).\n' +
    '- locPlanet: the world/planet this place belongs to ("Earth", "Faerun", "Tamriel"). One proper name.\n' +
    '- locPath: the ladder of containing places, COARSE TO FINE, separated by " > ", NOT including this place itself. Example: "Sword Coast > Neverwinter > Docks". 1-4 steps.\n' +
    '- locLat / locLon: plausible map coordinates as plain decimal numbers (latitude -90..90, longitude -180..180). Invent consistent ones for fictional worlds. Numbers only, no degree signs.\n' +
    '- locReach: how travellers normally arrive and how long it takes ("two days by carriage", "a short walk from the market").\n' +
    '- locFounded: when the place was built or founded, in the calendar this world actually uses ("1412", "Third Age 2931", "the second winter after the flood"). Just the date, no sentence.\n' +
    '- locHistory: leave EMPTY. It is filled by a separate pass that writes the dated chronicle.\n' +
    '- Leave a field empty ("") only when it genuinely does not apply.\n\n';

/* JSON stub of the location attribute keys, for the simple-mode prompt. */
function ccLocFieldsJsonStub() {
    var keys = ccLocAllKeys(false);
    var lines = [];
    for (var i = 0; i < keys.length; i++) {
        var sel = CC_LOC_SELECTS[keys[i]];
        var hint = sel ? ' /* one of: ' + sel.join(', ') + ' */' : '';
        lines.push('  "' + keys[i] + '": ""' + (i < keys.length - 1 ? ',' : '') + hint);
    }
    return lines.join('\n') + '\n';
}

