    if (d.personality || card.personality) parts.push('PERSONALITY:\n' + (d.personality || card.personality).substring(0, 1000));
    if (d.scenario || card.scenario) parts.push('SCENARIO:\n' + (d.scenario || card.scenario).substring(0, 800));
