async function comfyGenerate(wfObj) {
    var base = getComfyUrl();
    var qr = await fetch(base + '/prompt', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt: wfObj }) });
    if (!qr.ok) { var ei = ''; try { var ed = await qr.json(); ei = ed.error ? ed.error.message : JSON.stringify(ed).substring(0, 200); } catch (e) {} throw new Error('ComfyUI: ' + qr.status + ' ' + ei); }
    var pid = (await qr.json()).prompt_id;
    var dl = Date.now() + 180000;
    /* A turbo or LCM preset finishes in about four seconds, and a flat two-second
       poll spent up to half of that wait doing nothing at all — with six images
       in a row it was ten wasted seconds per page. Look early, then back off so
       a slow render still costs about one request per second. */
    var wait = 200;
    while (Date.now() < dl) {
        await new Promise(function (r) { setTimeout(r, wait); });
        wait = Math.min(1000, Math.round(wait * 1.35));
        /* Cancelling an emotions RUN drops out of the poll at once instead of
           waiting for the job (or the 3-minute timeout). Gated on
           ccEmotionsRunning so a stale cancel flag can never abort an unrelated
           generation (Dataset Lab, portraits) later on. */
        if (ccEmotionsRunning && ccEmotionsCancelled) return null;
        var hr; try { hr = await fetch(base + '/history/' + pid); if (!hr.ok) continue; } catch (e) { continue; }
        var hist = await hr.json(); if (!hist[pid]) continue;
        var entry = hist[pid];
        if (entry.status && entry.status.status_str === 'error') { var errMsg = 'ComfyUI error'; if (entry.status.messages) entry.status.messages.forEach(function (m) { if (m[0] === 'execution_error') errMsg = (m[1].node_type || '') + ': ' + (m[1].exception_message || '').substring(0, 200); }); throw new Error(errMsg); }
        var outs = entry.outputs; if (!outs || !Object.keys(outs).length) { if (entry.status && entry.status.completed) return null; continue; }
        /* Prefer the FINAL image: a SaveImage node and/or type 'output' — the
           first node in iteration order may be a PreviewImage or an
           intermediate save (e.g. the pre-RemBg picture). */
        var best = null;
        for (var nid in outs) {
            var imgs = outs[nid] && outs[nid].images; if (!imgs || !imgs.length) continue;
            var img = null;
            for (var xi = 0; xi < imgs.length; xi++) { if ((imgs[xi].type || 'output') === 'output') { img = imgs[xi]; break; } }
            var isFinalType = !!img; if (!img) img = imgs[0];
            var isSave = !!(wfObj && wfObj[nid] && wfObj[nid].class_type === 'SaveImage');
            var score = (isSave ? 2 : 0) + (isFinalType ? 1 : 0);
            if (!best || score > best.score) best = { img: img, score: score };
        }
        if (best) {
            var ir = await fetch(base + '/view?' + new URLSearchParams({ filename: best.img.filename, subfolder: best.img.subfolder || '', type: best.img.type || 'output' }).toString());
            if (ir.ok) { var blob = await ir.blob(); var reader = new FileReader();
                return await new Promise(function (res) { reader.onloadend = function () { res(reader.result.split(',')[1]); }; reader.readAsDataURL(blob); });
            }
        }
    }
    throw new Error('ComfyUI timeout (3 min)');
}

/* ══════════════════════════════════════
   COMFY — Upload image as base64 input
   (Required for LoadImageBase64 node)
   ══════════════════════════════════════ */

async function comfyUploadImage(b64, filename) {
    var base = getComfyUrl();
    var blob = b64ToBlob(b64, 'image/png');
    var fd = new FormData();
    fd.append('image', blob, filename || 'cc_input.png');
    fd.append('overwrite', 'true');
    var r;
    try {
        r = await fetch(base + '/upload/image', { method: 'POST', body: fd });
    } catch (e) {
        throw new Error('Cannot reach ComfyUI at ' + base + ': ' + e.message);
    }
    if (!r.ok) throw new Error('ComfyUI upload failed: ' + r.status);
    var data = await r.json();
    return data.name || filename;
}

/* Workflows with a %input_image_name% LoadImage slot need a file that actually
   exists in ComfyUI's input folder — 'empty.png' usually does not. Upload a
   black square once per session and reuse its name as the fallback. */
var _ccBlankInputName = null;
async function ccEnsureBlankInput() {
    if (_ccBlankInputName) return _ccBlankInputName;
    try { _ccBlankInputName = await comfyUploadImage(BLANK_PNG_512, 'cc_blank_input.png'); }
    catch (e) { E('blank input upload:', e.message); _ccBlankInputName = 'empty.png'; }
    return _ccBlankInputName;
}

/* ══════════════════════════════════════
   EMOTIONS — Core Generation Logic
   ══════════════════════════════════════ */

async function generateSingleEmotion(emotionLabel, avatarB64, uploadedName) {
    var emotionPrompt = EMOTION_PROMPTS[emotionLabel];
    if (!emotionPrompt) return null;

    var seed = Math.floor(Math.random() * 2147483647);

    // If an AutoIllustrator preset is selected, drive ComfyUI through it.
    if (isEmotionPresetSel()) {
        var preset = getEmotionPreset();
        if (!preset) throw new Error(T('noPreset'));

        /* Opening an existing set must not require ComfyUI. Upload the source
           avatar only when the user actually regenerates through a preset that
           consumes %input_image_name%. */
        if (!uploadedName && /%input_image_name%/.test(String(preset.workflow || '')) && avatarB64) {
            uploadedName = await comfyUploadImage(avatarB64, 'cc_review_avatar.png');
            if (ccReviewData) ccReviewData.uploadedName = uploadedName;
        }

        // Safety tags so the preset keeps a single solo subject + clean comp.
        var finalPrompt = emotionPrompt + ', solo, single person, looking at viewer, detailed face, simple background, keeping original character and outfit';
        var baseW = preset.width || 768, baseH = preset.height || 768;
        var neg = preset.negativePrompt || '';

        // Gemini preset: i2i from the avatar (an emotion sprite always starts from the reference).
        if (preset.useGemini) {
            return await geminiGenerate(preset, finalPrompt, neg, baseW, baseH, avatarB64 || null);
        }
        if (!preset.workflow) throw new Error(T('noPreset'));
        await ccPrepLoras(preset, finalPrompt);
        var wf = fillEmotionWorkflow(preset.workflow, finalPrompt, neg, baseW, baseH, preset, avatarB64, uploadedName, seed);
        if (!wf) throw new Error('Failed to parse emotions workflow.');
        return await comfyGenerate(wf);
    }

    // Otherwise use one of the built-in workflows.
    var workflow = buildEmotionWorkflow(avatarB64, emotionPrompt, seed);
    return await comfyGenerate(workflow);
}



/* ══════════════════════════════════════
   EMOTIONS — Core Generation Logic (Updated)
   ══════════════════════════════════════ */

async function doGenerateEmotions(charName) {
    var avatarB64 = null;
    if (ccData.avatarSource === 'face') avatarB64 = ccData.generatedFaceBase64;
    else if (ccData.avatarSource === 'fullbody') avatarB64 = ccData.generatedFullbodyBase64;
	else if (ccData.avatarSource === 'ref') avatarB64 = ccData.refImageBase64;
    else avatarB64 = ccData.generatedPortraitBase64;
    if (!avatarB64) avatarB64 = ccData.generatedPortraitBase64 || ccData.generatedFaceBase64 || ccData.generatedFullbodyBase64;

    if (!avatarB64) throw new Error(T('emotionsNoAvatar'));

    ccEmotionsCancelled = false;
    ccEmotionsRunning = true;
    var variantCount = ccData.emotionVariantCount || 1;
    var totalEmotions = EMOTION_LABELS.length * variantCount;
    var generated = [];
    var wasCancelled = false;

    showEmotionsOverlay(totalEmotions);

    try {
        var uploadedName;
        try {
            uploadedName = await comfyUploadImage(avatarB64, 'cc_avatar_' + charName.replace(/[^a-zA-Z0-9]/g, '_') + '.png');
        } catch (e) {
            throw new Error('Failed to upload avatar to ComfyUI: ' + e.message);
        }

        // Loop through emotions
        for (var i = 0; i < EMOTION_LABELS.length; i++) {
            if (ccEmotionsCancelled) break;

            var emotionLabel = EMOTION_LABELS[i];

            // Loop through variants
            for (var v = 0; v < variantCount; v++) {
                if (ccEmotionsCancelled) break;

                var currentIndex = (i * variantCount) + v;
                // Label for logging and UI: joy, joy-1, joy-2 etc.
                // Standard naming: base (index 0) has no suffix, others have -v
                var variantIndex = v; // 0, 1, 2...

                updateEmotionsProgress(currentIndex, totalEmotions, emotionLabel + (variantIndex > 0 ? '-'+variantIndex : ''));

                try {
                    var resultB64 = await generateSingleEmotion(emotionLabel, avatarB64, uploadedName);

                    if (resultB64) {
                        generated.push({ label: emotionLabel, index: variantIndex, b64: resultB64 });
                        addEmotionPreview(emotionLabel, variantIndex, resultB64);
                    } else if (!ccEmotionsCancelled) {
                        /* A null right after Cancel is the abort, not a failure. */
                        generated.push({ label: emotionLabel, index: variantIndex, b64: null, error: 'Empty result' });
                        updateEmotionsError(emotionLabel + '-'+variantIndex, 'Empty result');
                    }
                } catch (e) {
                    E('Emotion generation failed for', emotionLabel, 'variant', variantIndex, ':', e.message);
                    generated.push({ label: emotionLabel, index: variantIndex, b64: null, error: e.message });
                    updateEmotionsError(emotionLabel + '-'+variantIndex, e.message);
                }
            }
        }
        wasCancelled = ccEmotionsCancelled;
    } finally {
        /* Always clear the flags — a sticky "cancelled" used to be invisible
           until the next unrelated ComfyUI call behaved strangely. */
        ccEmotionsRunning = false;
        ccEmotionsCancelled = false;
        hideEmotionsOverlay();
    }

    var okCount = generated.filter(function (s) { return s.b64; }).length;

    /* Cancelled with nothing to show — the old behaviour. Cancelled part-way
       through, the already generated sprites go to review instead of the bin. */
    if (wasCancelled && !okCount) throw new Error(T('emotionsCancelled'));
    if (wasCancelled) showStatus(T('emotionsCancelled') + ' ' + okCount + ' sprite(s) kept for review.', 'info');

    showEmotionReviewModal(generated, charName, avatarB64, uploadedName);
    return { ok: okCount, total: totalEmotions };
}

/* ══════════════════════════════════════
   EMOTIONS — Review Modal UI (Updated)
   ══════════════════════════════════════ */

function showEmotionReviewModal(sprites, charName, avatarB64, uploadedName, reviewOptions) {
    hideEmotionReviewModal();

    var h = '<div class="cc-review-overlay" id="cc-review-overlay">';
    h += '<div class="cc-review-modal">';
    h += '<div class="cc-review-header"><h3>🎭 ' + esc(T('emotionsReviewTitle')) + '</h3><div class="cc-review-close" id="cc-review-close">×</div></div>';
    h += '<div class="cc-review-hint">' + esc(T('emotionsReviewHint')) + ' Use +/- to manage variants.</div>';
    h += '<div class="cc-review-grid" id="cc-review-grid">';

    // Sort sprites for consistent display
    sprites.sort(function(a, b) {
        if (a.label === b.label) return a.index - b.index;
        return EMOTION_LABELS.indexOf(a.label) - EMOTION_LABELS.indexOf(b.label);
    });

    for (var i = 0; i < sprites.length; i++) {
        var sp = sprites[i];
        h += createReviewItemHTML(sp, i);
    }

    h += '</div>'; // grid end
    h += '<div class="cc-review-footer">';
    h += '<div class="cc-review-mattebar">';
    h += '<label class="cc-review-chroma" title="Used for Regenerate, Add Variant, and the next sprite batch">';
    h += '<span class="cc-review-chroma-swatch" aria-hidden="true"></span>';
    h += '<span>Chroma key</span>';
    h += '<select id="cc-review-chroma" class="text_pole">';
    h += '<option value="#00ff00">Green (#00ff00)</option>';
    h += '<option value="#ff00ff">Magenta (#ff00ff)</option>';
    h += '</select></label>';
    h += '<details class="cc-review-matte"><summary><i class="fa-solid fa-sliders"></i> Matte settings</summary>';
    h += '<div class="cc-review-matte-pop">';
    h += '<div class="cc-review-matte-presets"><button type="button" class="menu_button" data-cc-matte-preset="uneven">Uneven AI background</button><button type="button" class="menu_button" data-cc-matte-preset="flat">Flat chroma</button></div>';
    h += '<div class="cc-review-matte-grid">';
    h += '<label>Key mode<select id="cc-review-key-mode" class="text_pole"><option value="auto_border">Auto border</option><option value="auto_corners">Auto corners</option><option value="manual">Manual color</option></select></label>';
    h += '<label>Transparent ≤<input id="cc-review-key-transparent" class="text_pole" type="number" min="0" max="254" step="1"></label>';
    h += '<label>Opaque ≥<input id="cc-review-key-opaque" class="text_pole" type="number" min="1" max="255" step="1"></label>';
    h += '<label>Tolerance<input id="cc-review-key-tolerance" class="text_pole" type="number" min="0" max="255" step="1"></label>';
    h += '<label>Edge contract<input id="cc-review-key-contract" class="text_pole" type="number" min="0" max="16" step="1"></label>';
    h += '<label>Edge feather<input id="cc-review-key-feather" class="text_pole" type="number" min="0" max="16" step="0.05"></label>';
    h += '<label class="cc-review-matte-check"><input id="cc-review-key-soft" type="checkbox"> Soft matte</label>';
    h += '<label class="cc-review-matte-check"><input id="cc-review-key-despill" type="checkbox"> Despill</label>';
    h += '</div><small>Changes apply to Regenerate, +, and the next batch. Auto border is recommended when the generated color is uneven.</small>';
    h += '</div></details></div>';
    h += '<div class="cc-review-actions">';
    h += '<button class="menu_button" id="cc-review-cancel">Cancel</button>';
    h += '<button class="menu_button cc-btn-success" id="cc-review-confirm"><i class="fa-solid fa-check"></i> ' + esc(T('emotionsConfirm')) + '</button>';
    h += '</div>';
    h += '</div>';
    h += '</div></div>';

    $('body').append(h);

    reviewOptions = reviewOptions || {};
    ccReviewData = {
        sprites: sprites,
        charName: charName,
        avatarB64: avatarB64,
        uploadedName: uploadedName,
        existingSet: !!reviewOptions.existingSet,
        originalFiles: Array.isArray(reviewOptions.originalFiles) ? reviewOptions.originalFiles.slice() : []
    };

    /* This is the same persisted option as Settings > Built-in chroma-key
       color. Workflow builders read it at call time, so Regenerate and + use
       the new color immediately without reopening either extension. */
    function syncReviewChromaSwatch() {
        var color = ccEmotionChromaColor();
        var matte = ccEmotionChromaSettings();
        $('#cc-review-chroma').val(color);
        $('.cc-review-chroma-swatch').css('background-color', color);
        $('#cc-review-key-mode').val(matte.key_mode);
        $('#cc-review-key-transparent').val(matte.transparent_threshold);
        $('#cc-review-key-opaque').val(matte.opaque_threshold);
        $('#cc-review-key-tolerance').val(matte.tolerance);
        $('#cc-review-key-contract').val(matte.edge_contract);
        $('#cc-review-key-feather').val(matte.edge_feather);
        $('#cc-review-key-soft').prop('checked', matte.soft_matte);
        $('#cc-review-key-despill').prop('checked', matte.despill);
    }
    function saveReviewMatteControls() {
        var low = ccClampChromaNumber($('#cc-review-key-transparent').val(), 0, 254, 36);
        var high = ccClampChromaNumber($('#cc-review-key-opaque').val(), 1, 255, 145);
        if (low >= high) high = Math.min(255, low + 1);
        ccSettings.emotionsChromaMode = $('#cc-review-key-mode').val();
        ccSettings.emotionsChromaTransparent = low;
        ccSettings.emotionsChromaOpaque = high;
        ccSettings.emotionsChromaTolerance = ccClampChromaNumber($('#cc-review-key-tolerance').val(), 0, 255, 32);
        ccSettings.emotionsChromaContract = Math.round(ccClampChromaNumber($('#cc-review-key-contract').val(), 0, 16, 1));
        ccSettings.emotionsChromaFeather = ccClampChromaNumber($('#cc-review-key-feather').val(), 0, 16, 0.35);
        ccSettings.emotionsChromaSoft = $('#cc-review-key-soft').prop('checked');
        ccSettings.emotionsChromaDespill = $('#cc-review-key-despill').prop('checked');
        saveSett();
        syncReviewChromaSwatch();
    }
    syncReviewChromaSwatch();
    $('#cc-review-chroma').on('change', function () {
        ccSettings.emotionsChromaKey = this.value === '#ff00ff' ? '#ff00ff' : '#00ff00';
        saveSett();
        $('#cc-s-emo-chroma').val(ccSettings.emotionsChromaKey);
        syncReviewChromaSwatch();
    });
    $('.cc-review-matte-pop').on('change', 'input, select', saveReviewMatteControls);
    $('.cc-review-matte-presets').on('click', '[data-cc-matte-preset]', function () {
        var uneven = $(this).attr('data-cc-matte-preset') === 'uneven';
        ccSettings.emotionsChromaMode = uneven ? 'auto_border' : 'manual';
        ccSettings.emotionsChromaSoft = true;
        ccSettings.emotionsChromaTransparent = uneven ? 36 : 12;
        ccSettings.emotionsChromaOpaque = uneven ? 145 : 220;
        ccSettings.emotionsChromaTolerance = uneven ? 32 : 12;
        ccSettings.emotionsChromaDespill = true;
        ccSettings.emotionsChromaContract = 1;
        ccSettings.emotionsChromaFeather = uneven ? 0.35 : 0;
        saveSett();
        syncReviewChromaSwatch();
    });

    // Event Handlers — closing discards GPU-minutes of sprites, so confirm first.
    $('#cc-review-close, #cc-review-cancel').on('click', function () {
        var n = (ccReviewData && ccReviewData.sprites)
            ? ccReviewData.sprites.filter(function (s) { return s.b64; }).length : 0;
        if (n && !confirm('Discard ' + n + ' generated sprite(s) without uploading?')) return;
        hideEmotionReviewModal();
    });

    $('#cc-review-confirm').on('click', async function() {
        var $btn = $(this).prop('disabled', true).html('<i class="fa-solid fa-circle-notch fa-spin"></i> ' + T('emotionsUploading'));
        var data = ccReviewData;
        var validSprites = data.sprites.filter(function(s) { return s.b64; });

        try {
            updateEmotionsStatus(T('emotionsUploading'));
            await uploadSpritesToCharacter(data.charName, validSprites);
            if (data.existingSet && data.originalFiles.length) {
                var kept = {};
                /* A file that failed to download remains represented by an
                   error tile; do not interpret that transport failure as a
                   user-requested deletion. Only tiles removed from the model
                   by the trash button are deleted. */
                data.sprites.forEach(function (sprite) {
                    kept[sprite.label + (sprite.index > 0 ? '-' + sprite.index : '')] = true;
                });
                var removed = data.originalFiles.filter(function (file) { return !kept[file]; });
                if (removed.length) await deleteSpritesFromCharacter(data.charName, removed);
            }
            hideEmotionReviewModal();
            showStatus(T('emotionsDone'), 'success');
            if (typeof toastr !== 'undefined') toastr.success('Emotions uploaded successfully!', 'Character Creator');
            /* Consumers such as Character Library can refresh their sprite
               count/grid after Apply without opening the Character Creator. */
            try {
                window.dispatchEvent(new CustomEvent('character-creator:emotion-sprites-applied', {
                    detail: { charName: data.charName, count: validSprites.length }
                }));
            } catch (eventError) { E('emotion apply event:', eventError); }
        } catch (e) {
            showStatus('Upload failed: ' + e.message, 'error');
            if (typeof toastr !== 'undefined') toastr.error('Upload failed: ' + e.message);
            $btn.prop('disabled', false).html('<i class="fa-solid fa-check"></i> ' + esc(T('emotionsConfirm')));
        }
    });

    // Delegate clicks for dynamic buttons
    $('#cc-review-grid').on('click', '.cc-review-regen', async function() {
        var $btn = $(this);
        var idx = parseInt($btn.data('idx'));
        var sp = ccReviewData.sprites[idx];

        $btn.html('<i class="fa-solid fa-circle-notch fa-spin"></i>');
        try {
            var newB64 = await generateSingleEmotion(sp.label, ccReviewData.avatarB64, ccReviewData.uploadedName);
            if (newB64) {
                sp.b64 = newB64;
                sp.error = null;
                updateReviewItem(idx, sp);
            } else {
                $btn.html('<i class="fa-solid fa-rotate"></i>');
            }
        } catch (e) {
            showStatus('Failed to regenerate ' + sp.label, 'error');
            $btn.html('<i class="fa-solid fa-rotate"></i>');
        }
    });

    // Add Variant Button
    $('#cc-review-grid').on('click', '.cc-review-add', async function() {
        var $btn = $(this);
        var label = $btn.data('label');

        $btn.html('<i class="fa-solid fa-circle-notch fa-spin"></i>');

        // Find max index for this label
        var maxIdx = 0;
        ccReviewData.sprites.forEach(function(s) {
            if (s.label === label && s.index > maxIdx) maxIdx = s.index;
        });

        var newIndex = maxIdx + 1;

        try {
            var newB64 = await generateSingleEmotion(label, ccReviewData.avatarB64, ccReviewData.uploadedName);
            if (newB64) {
                ccReviewData.sprites.push({ label: label, index: newIndex, b64: newB64 });
                reRenderReviewGrid();
            }
        } catch (e) {
            showStatus('Failed to add variant', 'error');
        }
        $btn.html('<i class="fa-solid fa-plus"></i>');
    });

    // Delete Variant Button
    $('#cc-review-grid').on('click', '.cc-review-delete', function() {
        var idx = parseInt($(this).data('idx'));
        var sp = ccReviewData.sprites[idx];

        if (sp.index === 0) {
            alert("Cannot delete the base emotion (Index 0). Only variants can be removed.");
            return;
        }

        ccReviewData.sprites.splice(idx, 1);
        /* Re-render fully so every data-idx stays accurate. */
        reRenderReviewGrid();
    });
}

function createReviewItemHTML(sp, arrayIndex) {
    var src = sp.b64 ? 'data:image/png;base64,' + sp.b64 : '';
    var errClass = sp.error ? 'cc-review-error' : '';
    var displayName = sp.label + (sp.index > 0 ? '-' + sp.index : '');

    var h = '<div class="cc-review-item ' + errClass + '" data-label="' + esc(sp.label) + '" data-idx="' + arrayIndex + '">';
    if (sp.b64) {
        // Adds data-cc-lightbox and data-idx
        h += '<img src="' + src + '" title="' + esc(displayName) + '" data-cc-lightbox="emotion" data-idx="' + arrayIndex + '">';
    } else {
        h += '<div class="cc-review-noimg">⚠️<br><small>Error</small></div>';
    }
    h += '<div class="cc-review-label">' + esc(displayName) + '</div>';
    h += '<div class="cc-review-controls">';

    h += '<button class="menu_button cc-review-regen" data-idx="' + arrayIndex + '" title="Regenerate"><i class="fa-solid fa-rotate"></i></button>';

    if (sp.index === 0) {
         h += '<button class="menu_button cc-review-add" data-label="' + esc(sp.label) + '" title="Add Variant"><i class="fa-solid fa-plus"></i></button>';
    }

    if (sp.index > 0) {
        h += '<button class="menu_button cc-btn-danger cc-review-delete" data-idx="' + arrayIndex + '" title="Delete Variant"><i class="fa-solid fa-trash"></i></button>';
    }

    h += '</div></div>';
    return h;
}

function updateReviewItem(arrayIndex, sp) {
    var $item = $('.cc-review-item[data-idx="' + arrayIndex + '"]');
    $item.removeClass('cc-review-error');
    var src = 'data:image/png;base64,' + sp.b64;
    var $img = $item.find('img');
    if ($img.length) {
        $img.attr('src', src);
    } else {
        /* The item was an error card — there is no <img> to update, build one. */
        var displayName = sp.label + (sp.index > 0 ? '-' + sp.index : '');
        $item.find('.cc-review-noimg').replaceWith(
            '<img src="' + src + '" title="' + esc(displayName) + '" data-cc-lightbox="emotion" data-idx="' + arrayIndex + '">');
    }
    $item.find('.cc-review-regen').html('<i class="fa-solid fa-rotate"></i>');
}

function reRenderReviewGrid() {
    if (!ccReviewData) return;
    var sprites = ccReviewData.sprites;
    sprites.sort(function(a, b) {
        if (a.label === b.label) return a.index - b.index;
        return EMOTION_LABELS.indexOf(a.label) - EMOTION_LABELS.indexOf(b.label);
    });

    var h = '';
    for (var i = 0; i < sprites.length; i++) {
        h += createReviewItemHTML(sprites[i], i);
    }
    $('#cc-review-grid').html(h);
}

function hideEmotionReviewModal() {
    $('#cc-review-overlay').remove();
    ccReviewData = null;
}

/* Upload generated sprites.
   One request per sprite (the old code uploaded every sprite TWICE and swallowed
   every error, so "Confirm & Upload" always looked successful). label carries the
   full variant name ('joy-1') — ST names the stored file <label>.png. Failures
   are collected and thrown so the caller can show a real error. */
async function uploadSpritesToCharacter(charName, sprites) {
    var headers = {};
    if (scriptModule && typeof scriptModule.getRequestHeaders === 'function') {
        try { headers = scriptModule.getRequestHeaders(); } catch (e) {}
    }
    var authHeaders = {};
    for (var hk in headers) {
        if (hk.toLowerCase() !== 'content-type') authHeaders[hk] = headers[hk];
    }

    var failed = [];
    for (var i = 0; i < sprites.length; i++) {
        var sprite = sprites[i];
        // Naming logic: joy.png or joy-1.png
        var filename = sprite.label + (sprite.index > 0 ? '-' + sprite.index : '');
        try {
            var fd = new FormData();
            fd.append('name', charName);
            fd.append('label', filename);
            fd.append('avatar', b64ToBlob(sprite.b64, 'image/png'), filename + '.png');

            var r = await fetch('/api/sprites/upload', {
                method: 'POST',
                headers: authHeaders,
                body: fd
            });
            if (!r.ok) throw new Error('HTTP ' + r.status);

            L('Uploaded sprite:', filename, 'for', charName);
        } catch (e) {
            E('Failed to upload sprite', filename, ':', e.message);
            failed.push(filename);
        }
    }

    if (failed.length) {
        throw new Error(failed.length + '/' + sprites.length + ' sprite(s) failed to upload: '
            + failed.slice(0, 5).join(', ') + (failed.length > 5 ? '…' : ''));
    }
}

async function deleteSpritesFromCharacter(charName, filenames) {
    var headers = { 'Content-Type': 'application/json' };
    if (scriptModule && typeof scriptModule.getRequestHeaders === 'function') {
        try { headers = scriptModule.getRequestHeaders(); } catch (e) {}
    }
    var failed = [];
    for (var i = 0; i < filenames.length; i++) {
        try {
            var r = await fetch('/api/sprites/delete', {
                method: 'POST',
                headers: headers,
                body: JSON.stringify({ name: charName, label: filenames[i], spriteName: filenames[i] })
            });
            if (!r.ok) throw new Error('HTTP ' + r.status);
        } catch (e) { failed.push(filenames[i]); }
    }
    if (failed.length) throw new Error('Could not delete sprite(s): ' + failed.join(', '));
}

function addEmotionPreview(label, index, b64) {
    var $preview = $('#cc-emo-preview');
    var displayName = label + (index > 0 ? '-'+index : '');
    $preview.append('<div style="display:flex;flex-direction:column;align-items:center"><img src="data:image/png;base64,' + b64 + '"><div class="cc-emo-label">' + esc(displayName) + '</div></div>');

    var done = $preview.find('img').length;
    var total = EMOTION_LABELS.length * (ccData.emotionVariantCount || 1);
    var pct = Math.round((done / total) * 100);
    $('#cc-emo-bar').css('width', pct + '%');
    $('#cc-emo-counter').text(done + ' / ' + total);
}


