/* ══════════════════════════════════════
   RECONSTRUCT FIELDS  (v3.6)
   Reverse pass: an existing card (loaded via Template / Load JSON, or
   typed by hand) is analysed by the LLM and its structured attributes —
   identity, body, species features, mind, abilities, outfits — are
   extracted back into the form. Locked fields and locked sections are
   never touched.
   ══════════════════════════════════════ */

var CC_RECON_MAX_CHARS = 12000;

/* Single source of truth — the per-feature copies had already drifted apart
   (temperament had 4 options here and 8 in the UI). */
var CC_RECON_SELECTS = CC_CHAR_SELECTS;

var CC_RECON_SLOTS = ['head', 'glasses', 'torso', 'arms', 'legs', 'feet', 'underwear', 'accessories'];

/* Enum options for a reconstructable field — character selects first, then the
   location / narrator selects (their keys never overlap). */
function ccReconSelects(key) {
    return CC_RECON_SELECTS[key] || CC_LOC_SELECTS[key] || null;
}

/* Location / narrator attributes to reconstruct, drawn from the very section
   schema the editor renders — so reconstruction fills exactly the type's fields. */
function ccReconFieldsLocNar() {
    var sectionFields = ccIsNar() ? CC_NAR_SECTION_FIELDS : CC_LOC_SECTION_FIELDS;
    var out = [], seen = {};
    for (var sid in sectionFields) {
        if (!sectionFields.hasOwnProperty(sid)) continue;
        var keys = sectionFields[sid];
        for (var i = 0; i < keys.length; i++) {
            var k = keys[i];
            if (seen[k]) continue;
            seen[k] = 1;
            out.push([k, k === 'name' ? 'Name' : (CC_LOC_LABELS[k] || k)]);
        }
    }
    return out;
}

/* Every attribute the reconstructor may fill (card text fields are NOT touched). */
function ccReconFields() {
    if (ccIsLoc() || ccIsNar()) return ccReconFieldsLocNar();
    var f = [
        ['name', 'Name'], ['race', 'Race / Species'], ['gender', 'Gender'], ['age', 'Age'],
        ['relationship', 'Relationship to the user'],
        ['height', 'Height'], ['weight', 'Weight'], ['musculature', 'Musculature'],
        ['bustSize', 'Bust Size'], ['buttocksSize', 'Buttocks Size'], ['legLength', 'Leg Length'],
        ['hairColor', 'Hair Color'], ['hairstyle', 'Hairstyle'], ['eyeColor', 'Eye Color'],
        ['fangs', 'Fangs / Teeth'], ['ears', 'Ears'], ['horns', 'Horns'], ['wings', 'Wings'],
        ['tail', 'Tail'], ['hooves', 'Hooves / Legs'], ['clawsNails', 'Claws / Nails'],
        ['skinFeatures', 'Skin / Scales / Fur'], ['otherFeatures', 'Other Features'],
        ['alignment', 'Alignment'], ['temperament', 'Temperament'],
        ['intelligence', 'Intelligence'], ['memory', 'Memory'], ['attention', 'Attention'], ['logic', 'Logic'],
        ['voiceTimbre', 'Voice Timbre'], ['mentalHealth', 'Mental Health'], ['diseases', 'Diseases / Conditions'],
        ['weapon', 'Personal Weapon'], ['abilities', 'Unique Abilities / Spells'], ['languages', 'Known Languages']
    ];
    if (ccSettings && ccSettings.showNSFW) {
        f.push(
            ['penisLengthErect', 'Penis Length (erect)'], ['penisLengthFlaccid', 'Penis Length (flaccid)'],
            ['penisGirthErect', 'Penis Girth (erect)'], ['penisGirthFlaccid', 'Penis Girth (flaccid)'],
            ['scrotumSize', 'Scrotum Size'], ['ejaculationVolume', 'Max Ejaculation Volume'],
            ['sizeTier', 'Hierarchy Tier'], ['semenVolumeMax', 'Max Semen Reserve'], ['ejaculationForce', 'Ejaculation Force'],
            ['libido', 'Libido'], ['stamina', 'Stamina before climax'], ['recoveryTime', 'Recovery Time'],
            ['lactation', 'Lactation'], ['milkVolume', 'Milk Output'], ['mutation', 'Mutation'],
            ['instinctControl', 'Instinct Control'], ['extraGenitals', 'Extra Genitals / Features']
        );
    }

    /* Labels carry the unit, so the field list itself tells the model what to write. */
    return f.map(function (row) {
        var unit = ccFieldUnit(row[0]);
        var hint = CC_LABEL_HINTS[row[0]] ? ' (' + CC_LABEL_HINTS[row[0]] + ')' : '';
        return unit ? [row[0], row[1] + hint + ', ' + unit] : [row[0], row[1] + hint];
    });
}

/* Source text for analysis: the card fields currently in the form,
   falling back to the raw loaded template text. */
function ccGatherCardSource() {
    var parts = [];
    if (ccData.name) parts.push('NAME: ' + ccData.name);
    if (ccData.description) parts.push('DESCRIPTION:\n' + ccData.description);
    if (ccData.personality) parts.push('PERSONALITY:\n' + ccData.personality);
    if (ccData.scenario) parts.push('SCENARIO:\n' + ccData.scenario);
    if (ccData.firstMessage) parts.push('FIRST MESSAGE:\n' + ccData.firstMessage);
    if (ccData.mesExample) parts.push('MESSAGE EXAMPLES:\n' + ccData.mesExample);
    if (ccData.altGreetings && ccData.altGreetings.length) {
        var alts = ccData.altGreetings.filter(function (a) { return a && a.trim(); });
        if (alts.length) parts.push('ALTERNATIVE GREETINGS:\n' + alts.join('\n---\n'));
    }
    var txt = parts.join('\n\n');
    if (!txt.trim() && ccData.templateText) txt = ccData.templateText;
    if (ccData.refImageDesc) txt += (txt ? '\n\n' : '') + 'REFERENCE IMAGE:\n' + ccData.refImageDesc;
    txt = txt.trim();
    if (txt.length > CC_RECON_MAX_CHARS) txt = txt.substring(0, CC_RECON_MAX_CHARS) + '\n...[truncated]';
    return txt;
}

function ccReconHasSource() { return !!ccGatherCardSource(); }

/* Reject junk the LLM sometimes returns for "no value". */
function ccReconIsBlank(val, key) {
    var v = String(val).trim().toLowerCase();
    if (!v || v === '-' || v === '—' || v === 'none' || v === 'unknown' || v === 'not specified' ||
        v === 'not mentioned' || v === 'null' || v === 'undefined') return true;
    if (v === 'n/a' && key !== 'bustSize') return true;   // "N/A" is a legit bustSize option
    return false;
}

/* ── The plan half (v3.56) ──
   Which fields this pass may write, and what the model is told about the rest.
   Extracted from doReconstructFields so BOTH sources — the card text and the
   avatar picture — decide it by the same rules. A second copy of "what may be
   overwritten" is exactly how one of the two would forget a lock (§6.5).

   Pure apart from reading ccData: takes the field list, returns three blocks. */
function ccReconPlan(all, opts) {
    opts = opts || {};
    var toFill = [], knownParts = [], lockedParts = [];

    for (var i = 0; i < all.length; i++) {
        var key = all[i][0], label = all[i][1], cur = ccData[key];
        var sec = SECTION_MAP[key];

        // Locked field or locked section — pass as context only, never overwrite
        if (isLocked(key) || (sec && isSectionLocked(sec))) {
            if (cur) lockedParts.push(label + ': ' + cur);
            continue;
        }
        // Already filled and overwrite is off — pass as context only
        if (!opts.overwrite && cur) {
            knownParts.push(label + ': ' + cur);
            continue;
        }
        var line = '- ' + key + ' (' + label + ')';
        var selOpts = ccReconSelects(key);
        if (selOpts) line += ' — choose EXACTLY one of: ' + selOpts.join(', ');
        toFill.push(line);
    }

    return { toFill: toFill, knownParts: knownParts, lockedParts: lockedParts };
}

/* ── The apply half (v3.56) ──
   The same three guards as the plan, applied again on the way IN: the plan
   decided what to ASK for, this decides what to KEEP, and the model is not
   trusted to have obeyed. Locks are hard guards here regardless of `overwrite`.
   -> number of fields written. */
function ccReconApplyData(all, data, opts) {
    opts = opts || {};
    var isLoc = ccIsLoc(), isNar = ccIsNar();
    var wantClothing = !!opts.clothing && !isLoc && !isNar;
    var filled = 0;

    for (var j = 0; j < all.length; j++) {
        var k = all[j][0];
        var s2 = SECTION_MAP[k];

        if (isLocked(k)) continue;                       // hard guard
        if (s2 && isSectionLocked(s2)) continue;         // hard guard
        if (!opts.overwrite && ccData[k]) continue;

        var val = data[k];
        if (val === undefined || val === null) continue;
        if (typeof val !== 'string') val = String(val);
        val = val.trim();
        if (ccReconIsBlank(val, k)) continue;

        var selOpts2 = ccReconSelects(k);
        if (selOpts2) val = matchSelectOption(val, selOpts2);
        ccData[k] = val;
        filled++;
    }

    if (wantClothing && Array.isArray(data.outfits) && data.outfits.length) {
        var outs = [];
        for (var o = 0; o < data.outfits.length && o < 5; o++) {
            var srcO = data.outfits[o];
            if (!srcO || typeof srcO !== 'object') continue;
            var out = { name: (srcO.name ? String(srcO.name).trim() : '') || ('Outfit ' + (o + 1)) };
            var any = false;
            for (var s = 0; s < CC_RECON_SLOTS.length; s++) {
                var sv = srcO[CC_RECON_SLOTS[s]];
                sv = (sv === undefined || sv === null) ? '' : String(sv).trim();
                if (ccReconIsBlank(sv, CC_RECON_SLOTS[s])) sv = '';
                out[CC_RECON_SLOTS[s]] = sv;
                if (sv) any = true;
            }
            if (any) outs.push(out);
        }
        if (outs.length) {
            ccData.outfits = outs;
            if (ccData.currentOutfitIdx >= outs.length) ccData.currentOutfitIdx = 0;
            filled += outs.length;
        }
    }

    return filled;
}

/* opts = { overwrite: bool, infer: bool, clothing: bool } */
async function doReconstructFields(opts) {
    if (!genQuiet) throw new Error(T('noLLM'));
    opts = opts || {};

    var isLoc = ccIsLoc(), isNar = ccIsNar();

    var source = ccGatherCardSource();
    if (!source) throw new Error(T('reconNoCard'));

    var all = ccReconFields();
    var plan = ccReconPlan(all, opts);
    var toFill = plan.toFill, knownParts = plan.knownParts, lockedParts = plan.lockedParts;

    var wantClothing = !!opts.clothing && !isLoc && !isNar;   // outfits are a character-only concept
    if (!toFill.length && !wantClothing) throw new Error(T('reconNothing'));

    // Type-aware framing so the model reconstructs a place / narrator, not a person.
    var subject = isNar ? 'narrator' : (isLoc ? 'location' : 'character');
    var applyRule = isNar
        ? '3. If a field genuinely does not apply to this narrator, return an empty string "".\n'
        : isLoc
            ? '3. If a field genuinely does not apply to this location, return an empty string "".\n'
            : '3. If a field genuinely does not apply to this character (bust size for a male, horns for a human, penis fields for a female), return an empty string "".\n';
    var lengthRule = (isLoc || isNar)
        ? '5. Enum-like fields must be EXACTLY one listed option; descriptive fields (layout, atmosphere, secrets, duties, forbidden, …) may be a short phrase or 1-2 sentences.\n'
        : '5. Keep values SHORT — a word or a brief phrase. Exception: "abilities" may be 1-3 sentences.\n';

    var inferRule = opts.infer
        ? ((isLoc || isNar)
            ? '2. If a field is NOT stated in the card, INFER the most plausible value from the ' + subject + '\'s established details, atmosphere and internal logic. Leave applicable fields empty only as a last resort.\n'
            : '2. If a field is NOT stated in the card, INFER the most plausible value from the character\'s race, age, personality, behaviour and speech. Leave applicable fields empty only as a last resort.\n')
        : '2. If a field is NOT stated or clearly implied in the card, return an empty string "" — DO NOT invent anything.\n';

    var clothingRule = wantClothing
        ? '7. Also reconstruct the character\'s OUTFITS from the card. Return an "outfits" array with 1-3 entries, each shaped:\n' +
          '   {"name": "Everyday", "head": "", "glasses": "", "torso": "", "arms": "", "legs": "", "feet": "", "underwear": "", "accessories": ""}\n' +
          '   Use short garment descriptions per slot; leave a slot as "" when the card says nothing about it. The first outfit must be the one the character is described as currently wearing.\n\n'
        : '';

    var prompt = PROMPTS.reconstructFields
        .replace(/\{\{SUBJECT\}\}/g, subject)
        .replace('{{CARD}}', source)
        .replace('{{KNOWN_BLOCK}}', knownParts.length ? 'ALREADY FILLED (context only — do NOT output these keys):\n' + knownParts.join('\n') + '\n\n' : '')
        .replace('{{LOCKED_BLOCK}}', lockedParts.length ? 'LOCKED (context only — do NOT output these keys):\n' + lockedParts.join('\n') + '\n\n' : '')
        .replace('{{INFER_RULE}}', inferRule)
        .replace('{{APPLY_RULE}}', applyRule)
        .replace('{{LENGTH_RULE}}', lengthRule)
        .replace('{{FIELD_LIST}}', toFill.length ? toFill.join('\n') : '(no attribute keys — only the outfits array)')
        .replace('{{CLOTHING_RULE}}', clothingRule)
        .replace('{{CLOTHING_KEY}}', wantClothing ? ' plus the "outfits" array' : '');
    prompt = prompt.replace('{{UNITS_BLOCK}}', ccUnitsBlock());

    var raw = await ccGenQuiet(prompt);
    var data = parseJSON(raw);
    if (!data || typeof data !== 'object') throw new Error('Failed to parse LLM response.');

    var filled = ccReconApplyData(all, data, opts);

    L('Reconstruct fields done. Filled:', filled);
    return filled;
}

/* ══════════════════════════════════════
   v3.56 — LOCK & FILL, AND FILLING FROM THE AVATAR
   ══════════════════════════════════════ */

/* The picture the card is currently wearing — the SAME chain Create uses when
   it uploads an avatar, so "what the model looks at" and "what the card will
   be" are one answer.

   Deliberately NOT shared with doGenerateEmotions, which runs its own copy of
   these four lines: that copy leaves refImageBase64 out of the FALLBACK on
   purpose (an emotion sheet is made from a generated face, not from somebody's
   reference photo). Merging them would be one owner for two questions. */
function ccActiveAvatarB64() {
    var src = ccData.avatarSource;
    var b64 = (src === 'face') ? ccData.generatedFaceBase64
        : (src === 'fullbody') ? ccData.generatedFullbodyBase64
            : (src === 'ref') ? ccData.refImageBase64
                : ccData.generatedPortraitBase64;
    if (!b64) {
        b64 = ccData.generatedPortraitBase64 || ccData.generatedFaceBase64
            || ccData.generatedFullbodyBase64 || ccData.refImageBase64;
    }
    return b64 || null;
}

/* ── Transient locks ──
   Locking every filled field before a fill pass and putting the locks back
   afterwards. The lock is a TOOL here, not a state the user asked for: after
   the button has run, the padlocks are exactly what they were before it — if
   a field was locked by hand it stays locked, if it was not it does not
   suddenly become so.

   Two things make that promise hold:

   * `finally` — the restore runs on the failure path too. A pass that threw
     halfway would otherwise leave a card silently padlocked from top to
     bottom, and the next Reconstruct would quietly do nothing.
   * the IDENTITY guard — the pass awaits, and during an await the editor can
     be loaded with a different card, which REPLACES ccData.locked with that
     card's own map (ccApplyCard). Restoring into the new object would strip
     locks the new card legitimately carries. So the restore only touches the
     very object it mutated; if the slot now holds a different one, the locks
     we added went away with the old card and there is nothing to undo (§6.1).

   -> whatever `run` returned. */
async function ccWithTransientLocks(keys, run) {
    if (!ccData.locked) ccData.locked = {};
    var lockRef = ccData.locked;
    var added = [];

    for (var i = 0; i < keys.length; i++) {
        if (lockRef[keys[i]]) continue;      // already locked by hand — not ours to undo
        lockRef[keys[i]] = true;
        added.push(keys[i]);
    }

    try {
        return await run();
    } finally {
        if (ccData.locked === lockRef) {
            for (var j = 0; j < added.length; j++) delete lockRef[added[j]];
        }
    }
}

/* Every attribute of the current card type that already has a value. This —
   not "every field" — is what Lock & Fill locks: locking the empty ones too
   would leave the pass with nothing it is allowed to write. */
function ccFilledReconKeys() {
    var all = ccReconFields();
    var out = [];
    for (var i = 0; i < all.length; i++) {
        var k = all[i][0];
        if (String(ccData[k] == null ? '' : ccData[k]).trim()) out.push(k);
    }
    return out;
}

/* ── Lock & Fill ──
   Protect what is already there, fill in everything else, hand the padlocks
   back as they were.

   It sets its own terms rather than reading the panel's checkboxes, because
   that is the whole promise of the button:
     overwrite — irrelevant by construction (everything filled is locked), and
                 forced off so the guard is doubled rather than trusted once;
     infer     — ON: "fill every empty field" is not possible otherwise, the
                 model would answer "" for everything the card does not state;
     clothing  — the panel's checkbox, because outfits are the one part the
                 user may genuinely not want rebuilt. */
async function doLockAndFill(opts) {
    opts = opts || {};
    var keys = ccFilledReconKeys();
    var n = await ccWithTransientLocks(keys, function () {
        return doReconstructFields({ overwrite: false, infer: true, clothing: !!opts.clothing });
    });
    return { filled: n, locked: keys.length };
}

/* ── Fill from the avatar ──
   The same reconstruction with the picture as the source. Everything is shared
   with the text pass except two things: what the model is shown, and how the
   answer is fetched — a vision call instead of a quiet prompt.

   The card text still travels as CONTEXT (trimmed), so the picture cannot
   invent a name the card already answers to. */
var CC_IMG_RECON_CONTEXT_MAX = 1500;

async function doReconstructFromAvatar(opts) {
    opts = opts || {};

    var b64 = ccActiveAvatarB64();
    if (!b64) throw new Error(T('reconImgNoAvatar'));

    var isLoc = ccIsLoc(), isNar = ccIsNar();
    var subject = isNar ? 'narrator' : (isLoc ? 'location' : 'character');

    var all = ccReconFields();
    var plan = ccReconPlan(all, opts);

    var wantClothing = !!opts.clothing && !isLoc && !isNar;
    if (!plan.toFill.length && !wantClothing) throw new Error(T('reconNothing'));

    var applyRule = isNar
        ? '3. If a field genuinely does not apply to this narrator, return an empty string "".\n'
        : isLoc
            ? '3. If a field genuinely does not apply to this location, return an empty string "".\n'
            : '3. If a field genuinely does not apply to this character (bust size for a male, horns for a human, penis fields for a female), return an empty string "".\n';
    var lengthRule = (isLoc || isNar)
        ? '5. Enum-like fields must be EXACTLY one listed option; descriptive fields may be a short phrase or 1-2 sentences.\n'
        : '5. Keep values SHORT — a word or a brief phrase. Exception: "abilities" may be 1-3 sentences.\n';

    /* The heart of "or make it up if the photo cannot say": a picture holds a
       body, never a memory or a language. With inference off the honest answer
       for those is silence, and the prompt says so instead of pretending. */
    var inferRule = opts.infer
        ? '2. For anything a picture CANNOT show — temperament, intelligence, memory, attention, logic, languages, abilities, health — INVENT the most plausible value that FITS the figure you see (their bearing, dress, wear and tear, apparent age). Leave an applicable field empty only as a last resort.\n'
        : '2. If the picture does not SHOW it, return an empty string "" — do not guess.\n';

    var clothingRule = wantClothing
        ? '7b. Also read the character\'s OUTFIT off the picture. Return an "outfits" array with exactly 1 entry, shaped:\n' +
          '   {"name": "Everyday", "head": "", "glasses": "", "torso": "", "arms": "", "legs": "", "feet": "", "underwear": "", "accessories": ""}\n' +
          '   Fill only the slots you can actually see; leave the rest as "". Never guess underwear that is not visible.\n\n'
        : '';

    var cardSrc = ccGatherCardSource();
    if (cardSrc && cardSrc.length > CC_IMG_RECON_CONTEXT_MAX) {
        cardSrc = cardSrc.substring(0, CC_IMG_RECON_CONTEXT_MAX) + '\n...[truncated]';
    }

    var prompt = PROMPTS.reconstructFromImage
        .replace(/\{\{SUBJECT\}\}/g, subject)
        .replace('{{CARD_BLOCK}}', cardSrc ? 'THE CARD SO FAR (context — do not contradict it):\n--- CARD ---\n' + cardSrc + '\n--- END CARD ---\n\n' : '')
        .replace('{{KNOWN_BLOCK}}', plan.knownParts.length ? 'ALREADY FILLED (context only — do NOT output these keys):\n' + plan.knownParts.join('\n') + '\n\n' : '')
        .replace('{{LOCKED_BLOCK}}', plan.lockedParts.length ? 'LOCKED (context only — do NOT output these keys):\n' + plan.lockedParts.join('\n') + '\n\n' : '')
        .replace('{{UNITS_BLOCK}}', ccUnitsBlock())
        .replace('{{INFER_RULE}}', inferRule)
        .replace('{{APPLY_RULE}}', applyRule)
        .replace('{{LENGTH_RULE}}', lengthRule)
        .replace('{{FIELD_LIST}}', plan.toFill.length ? plan.toFill.join('\n') : '(no attribute keys — only the outfits array)')
        .replace('{{CLOTHING_RULE}}', clothingRule)
        .replace('{{CLOTHING_KEY}}', wantClothing ? ' plus the "outfits" array' : '');

    /* force: this needs a multimodal model. The Extras fallback answers prose,
       and prose parsed as JSON is a wrong answer wearing the right shape. */
    var raw = await ccCaptionImage(b64, { prompt: prompt, maxTokens: 1500, force: true });
    var data = parseJSON(raw);
    if (!data || typeof data !== 'object') throw new Error(T('reconImgUnparsed'));

    var filled = ccReconApplyData(all, data, opts);
    L('Reconstruct from avatar done. Filled:', filled);
    return filled;
}

/* Fill from the avatar, without touching what is already written: the same
   transient locks Lock & Fill uses, so a picture can never overwrite the
   author. When the user has ticked Overwrite they asked for the opposite, and
   then the locks are not applied at all. */
async function doLockAndFillFromAvatar(opts) {
    opts = opts || {};
    if (opts.overwrite) {
        var m = await doReconstructFromAvatar(opts);
        return { filled: m, locked: 0 };
    }
    var keys = ccFilledReconKeys();
    var n = await ccWithTransientLocks(keys, function () {
        return doReconstructFromAvatar({ overwrite: false, infer: opts.infer, clothing: opts.clothing });
    });
    return { filled: n, locked: keys.length };
}

async function doUIReconstructFields() {
    if (ccBusy) return;
    ccBusy = true;
    var $btn = $('#cc-recon-btn');
    var old = $btn.html();
    $('#cc-recon-btn, #cc-f-reconstruct').prop('disabled', true);
    $btn.html('<i class="fa-solid fa-circle-notch fa-spin"></i> ' + esc(T('reconRunning')));
    showStatus(T('reconRunning'), 'info');
    try {
        var n = await doReconstructFields({
            overwrite: !!ccData._reconOverwrite,
            infer: ccData._reconInfer !== false,
            clothing: ccData._reconClothing !== false
        });
        renderBody();
        showStatus(T('reconDone').replace('{{N}}', n), n ? 'success' : 'info');
    } catch (e) {
        E(e);
        showStatus(e.message, 'error');
        $('#cc-recon-btn').html(old);
    }
    ccBusy = false;
    $('#cc-recon-btn, #cc-f-reconstruct').prop('disabled', false);
}

/* One busy-guard, one re-render, one status line for both new buttons — they
   differ only in what they run and what they say. `run` returns
   { filled, locked }. */
async function ccRunFillPass(btnSel, runningKey, run, doneMsg) {
    if (ccBusy) return;
    ccBusy = true;
    var $btn = $(btnSel);
    var old = $btn.html();
    $('#cc-recon-btn, #cc-f-reconstruct, #cc-lockfill-btn, #cc-recon-img-btn').prop('disabled', true);
    $btn.html('<i class="fa-solid fa-circle-notch fa-spin"></i> ' + esc(T(runningKey)));
    showStatus(T(runningKey), 'info');
    try {
        var r = await run();
        renderBody();
        showStatus(doneMsg(r), r.filled ? 'success' : 'info');
    } catch (e) {
        E(e);
        showStatus(e.message, 'error');
    }
    ccBusy = false;
    /* renderBody() rebuilt the panel, so the buttons here are fresh nodes —
       re-enabling by selector, never by the captured jQuery object. */
    $('#cc-recon-btn, #cc-f-reconstruct, #cc-lockfill-btn, #cc-recon-img-btn').prop('disabled', false);
    if (!$(btnSel).length) return;
    if ($(btnSel).html().indexOf('fa-spin') !== -1) $(btnSel).html(old);
}

function doUILockAndFill() {
    return ccRunFillPass('#cc-lockfill-btn', 'lockFillRunning', function () {
        return doLockAndFill({ clothing: ccData._reconClothing !== false });
    }, function (r) {
        return T('lockFillDone').replace('{{N}}', r.filled).replace('{{L}}', r.locked);
    });
}

function doUIReconstructFromAvatar() {
    return ccRunFillPass('#cc-recon-img-btn', 'reconImgRunning', function () {
        return doLockAndFillFromAvatar({
            overwrite: !!ccData._reconOverwrite,
            infer: ccData._reconInfer !== false,
            clothing: ccData._reconClothing !== false
        });
    }, function (r) {
        return T('reconImgDone').replace('{{N}}', r.filled);
    });
}

/* ══════════════════════════════════════
   RECONSTRUCT BIO
   ══════════════════════════════════════ */

/* ── the chronicle of a place (v3.37) ──
   A character's biography is measured against a KNOWN span: age is on the card,
   so the code picks the years and the model fills them in. A place has no such
   span — a card carries the year it was built and no notion of "now" — and its
   history is lumpy by nature: built, then nothing for decades, then a fire, a
   siege, a slow decay. A distribution grid would flatten exactly what makes a
   chronicle worth reading, so here the model owns the dates and the prompt
   constrains their SHAPE instead: anchored on the founding date, strictly
   forward, ending today, deliberately uneven.

   Pure on purpose — every fact arrives as an argument, so it is testable in
   node without a card, a DOM or a backend. */
function ccLocChroniclePrompt(o) {
    o = o || {};
    var name = String(o.name || '').trim() || 'this place';
    var founded = String(o.founded || '').trim();
    var count = Math.max(2, Math.min(30, Number(o.count) || 8));
    var rooms = (o.rooms || []).filter(Boolean).slice(0, 16);
    var lines = [];
    lines.push('[OOC: You are the chronicler of a place. Respond with the chronicle only.');
    lines.push('');
    lines.push('THE PLACE:');
    lines.push(String(o.context || '(no details — be creative)'));
    lines.push('');
    lines.push('TASK: write exactly ' + count + ' milestones in the history of ' + name +
        ', from the day it was built to the present day of the story.');
    lines.push('');
    lines.push('RULES:');
    lines.push('• The FIRST milestone is the founding, dated exactly "' + founded +
        '" as written above. Keep that calendar and that format for every later date — do not convert it into another era or add a calendar the card never mentioned.');
    lines.push('• Begin every milestone with its own date, then " — ", then the event.');
    lines.push('• Dates move strictly forward. The LAST milestone is the present day — the state the card describes right now.');
    lines.push('• Do NOT space the milestones evenly. A place\'s history clusters: it is built, then nothing happens for a long time, then several things happen at once. Leave long silences and tight bursts.');
    lines.push('• Each milestone is 2-4 sentences, concrete: who did what here, and what it left behind.');
    lines.push('• Everything must EXPLAIN what the card already says — the current owner, status, condition, hazards, secrets, rumours and the landmarks listed — never contradict it. The present-day state is the destination the chronicle arrives at.');
    if (rooms.length) {
        lines.push('• The floor plan of this place names these rooms: ' + rooms.join(', ') +
            '. Where it is natural, let the history account for them — who added a wing, what a room used to be before, which door was walled up.');
    }
    lines.push('• No headings, no numbering, no bullet markers, no preamble. One paragraph per milestone, separated by a blank line.');
    lines.push('• Write in the same language as the card above.');
    lines.push(']');
    return lines.join('\n');
}

/* Room names from the drawn plan, if there is one. Nothing invented: no plan
   means no clause in the prompt at all (§6.8). */
function ccLocPlanRooms() {
    /* Whichever geometry this card is playing — the rooms are the rooms, and a
       reader that knew only about plans would go quiet on a dollhouse card. */
    if (ccGeomMode(ccData) === 'dollhouse') {
        var dh = ccData.locDollhouse;
        var outD = [];
        ((dh && dh.floors) || []).forEach(function (f) {
            (f.cells || []).forEach(function (c) {
                var nm = String((c && (c.name || c.id)) || '').trim();
                if (nm) outD.push(nm);
            });
        });
        return outD;
    }
    var bp = ccData.locBlueprint;
    if (!bp || !Array.isArray(bp.floors)) return [];
    var out = [];
    bp.floors.forEach(function (f) {
        (f.rooms || []).forEach(function (r) {
            var nm = String((r && (r.name || r.id)) || '').trim();
            if (nm) out.push(nm);
        });
    });
    return out;
}

async function doReconstructLocHistory(count) {
    var founded = String(ccData.locFounded || '').trim();
    if (!founded) throw new Error('Set "Built / Founded" on the Basic tab first — the chronicle is anchored on it.');
    var prompt = ccLocChroniclePrompt({
        name: ccData.name,
        founded: founded,
        count: count,
        context: gatherLocContext(['locHistory']),
        rooms: ccLocPlanRooms(),
    });
    var raw = await ccGenQuiet(prompt);
    return String(raw || '').trim();
}

async function doReconstructBio(memoryCount) {
    if (!genQuiet) throw new Error(T('noLLM'));

    /* A place is not a person with an age: it gets the dated chronicle instead.
       A narrator is neither — the panel is not rendered for one. */
    if (ccIsLoc()) return await doReconstructLocHistory(memoryCount);

    var name    = ccData.name    || 'the character';
    var age     = parseInt(ccData.age) || 0;
    var race    = ccData.race    || '';
    var gender  = ccData.gender  || '';
    var context = gatherContext();

    if (age <= 0) throw new Error('Please set the character\'s age before reconstructing biography.');

    // Generate random-ish timestamps spread across age with slight jitter
    // Always include birth (age 0)
    var total = Math.max(2, memoryCount);
    var points = [0];

    // Distribute remaining events across the lifespan with randomness
    var interval = age / (total - 1);
    for (var i = 1; i < total - 1; i++) {
        var base = interval * i;
        var jitter = (Math.random() - 0.5) * interval * 0.7;
        var pt = Math.round(Math.max(1, Math.min(age - 1, base + jitter)));
        points.push(pt);
    }
    points.push(age); // last event = current age
    // deduplicate and sort
    points = points.filter(function (v, i, a) { return a.indexOf(v) === i; }).sort(function (a, b) { return a - b; });

    var prompt = '[OOC: You are a narrative biographer. Generate a detailed biography for a character based on the info below.\n\n' +
        'CHARACTER INFO:\n' + context + '\n\n' +
        'TASK: Write exactly ' + points.length + ' biographical memories/events for ' + name + '.\n' +
        'The events must occur at these ages (in years): ' + points.join(', ') + '\n\n' +
        'Rules:\n' +
        '- Each memory must be 3-4 sentences long (a short paragraph).\n' +
        '- Start each memory with "Age X:" where X is the age.\n' +
        '- Age 0 must be the birth event.\n' +
        '- Events should be plausible, varied and consistent with character personality, race, abilities and backstory.\n' +
        '- Do NOT use equal time intervals — reflect the given ages exactly.\n' +
        '- Write in third person.\n' +
        '- Match the language of the character context.\n\n' +
        'Output ONLY the biography events, one paragraph per event, separated by a blank line. No JSON, no headers, no preamble.]';

    var raw = await ccGenQuiet(prompt);
    return raw.trim();
}

