async function doUIGenerate() {
    if (ccBusy) return; ccBusy = true;
    var $btn = $('#cc-f-generate').prop('disabled', true).html('<i class="fa-solid fa-circle-notch fa-spin"></i> ' + esc(T('generating')));
    showStatus(T('generating'), 'info');
    try {
        if (ccData.mode === 'simple') await doSimpleGenerate();
        else await doAdvancedGenerate();
        renderBody(); showStatus(T('charGenSuccess'), 'success');
        if (ccData.mode === 'advanced') {
            ccData.activeTab = 'card'; $('.cc-tab').removeClass('active'); $('.cc-tab[data-tab="card"]').addClass('active'); renderBody();
        }
    } catch (e) { showStatus(e.message, 'error'); E('Generate:', e); }
    ccBusy = false; $btn.prop('disabled', false).html('<i class="fa-solid fa-wand-magic-sparkles"></i> ' + esc(T('generate')));
}

/* v3.80: a locked picture is edited, not redrawn. */
async function doUIEditLockedImage(view) {
    if (!ccEditPreset()) { showStatus(T('imgEditNoPreset'), 'error'); return; }
    ccBusy = true;
    var $ic = $('.cc-img-gen[data-cc-gen="' + view + '"] i').attr('class', 'fa-solid fa-circle-notch fa-spin');
    showStatus(T('imgEditing'), 'info');
    try {
        var b64 = await doEditLockedImage(view);
        if (!b64) {
            /* Nothing visible changed in the fields: the author says what. The
               spinner stays up across the question — the work is still pending. */
            var ask = window.prompt(T('imgEditAsk'), '');
            if (ask && ask.trim()) b64 = await doEditLockedImage(view, { text: ask.trim() + ccEditKeepClause() });
        }
        if (b64) { renderBody(); showStatus(T('imgEdited'), 'success'); }
        else $ic.attr('class', 'fa-solid fa-pen-to-square');
    } catch (e) {
        showStatus(e.message, 'error'); E('Image edit:', e);
        $ic.attr('class', 'fa-solid fa-pen-to-square');
    }
    ccBusy = false;
}

async function doUIGenImage(imageType) {
    if (ccBusy) return;
    if (ccImgIsLocked(imageType)) return doUIEditLockedImage(imageType);
    var preset = getAIActivePreset();
    if (!preset || (!preset.workflow && !preset.useGemini)) { showStatus(T('noPreset'), 'error'); return; }
    if (!genQuiet) { showStatus(T('noLLM'), 'error'); return; }
    if (!ccData.name && !ccData.description && !ccData.simpleIdea) { showStatus(T('enterInfoFirst'), 'error'); return; }
    ccBusy = true;
    var btnMap = { face: '#cc-f-genface', portrait: '#cc-f-genportrait', fullbody: '#cc-f-genfull' };
    var $btn = $(btnMap[imageType]).prop('disabled', true).html('<i class="fa-solid fa-circle-notch fa-spin"></i>');
    showStatus(T('generatingImage'), 'info');
    try { await doGenerateImage(imageType); renderBody(); showStatus(T('imgGenerated'), 'success'); }
    catch (e) { showStatus(e.message, 'error'); E('Image:', e); }
    ccBusy = false;
    var labels = { face: T('face'), portrait: T('portrait'), fullbody: T('fullbody') };
    var icons = { face: 'fa-circle-user', portrait: 'fa-image-portrait', fullbody: 'fa-person' };
    $btn.prop('disabled', false).html('<i class="fa-solid ' + icons[imageType] + '"></i> ' + esc(labels[imageType]));
}

async function doUICreateCharacter() {
    if (ccBusy) return;
    if (!ccData.name || !ccData.name.trim()) { showStatus(T('nameRequired'), 'error'); return; }
    if (!ccData.description) { showStatus(T('descRequired'), 'error'); return; }
    ccBusy = true;
    var $btn = $('#cc-f-create').prop('disabled', true).html('<i class="fa-solid fa-circle-notch fa-spin"></i> ' + esc(T('creatingChar')));
    try {
        var name = await doCreateCharacter();
        showStatus('"' + name + '"' + T('charCreated'), 'success');
        if (typeof toastr !== 'undefined') toastr.success(name + T('charCreated'), T('title'));

        /* ═══ EMOTIONS GENERATION ═══ */
        if (ccData.generateEmotions && ccSettings.generateAvatar) {
            try {
                var emoRes = await doGenerateEmotions(name);
                showStatus(T('emotionsDone') + ' (' + emoRes.ok + '/' + emoRes.total + ')', 'success');
                if (typeof toastr !== 'undefined') toastr.success(emoRes.ok + ' emotion sprites generated!', 'Character Creator');
            } catch (emoErr) {
                if (emoErr.message === T('emotionsCancelled')) {
                    showStatus(T('emotionsCancelled'), 'info');
                    if (typeof toastr !== 'undefined') toastr.warning(T('emotionsCancelled'));
                } else {
                    showStatus('Emotions error: ' + emoErr.message, 'error');
                    E('Emotions:', emoErr);
                    if (typeof toastr !== 'undefined') toastr.error('Emotions: ' + emoErr.message);
                }
            }
        }
    } catch (e) { showStatus(e.message, 'error'); E('Create:', e); }
    ccBusy = false; $btn.prop('disabled', false).html('<i class="fa-solid fa-check"></i> ' + esc(T('create')));
}

/* ══════════════════════════════════════
   LLM EDIT (v3.4) — free-form card editing via LLM
   User types an instruction ("rename everyone to Alice",
   "add to her bio that she met {{user}} at 14"), the LLM
   returns ONLY the changed fields, user reviews a diff
   and applies selected changes.
   ══════════════════════════════════════ */

/* Fields the LLM is allowed to see & edit, grouped by scope. */
var CC_EDIT_ATTR_KEYS = [
    'name', 'race', 'gender', 'age', 'height', 'weight', 'musculature',
    'hairColor', 'hairstyle', 'eyeColor', 'bustSize', 'buttocksSize', 'legLength',
    'fangs', 'ears', 'horns', 'wings', 'tail', 'hooves', 'clawsNails', 'skinFeatures', 'otherFeatures',
    'alignment', 'temperament', 'intelligence', 'memory', 'attention', 'logic',
    'voiceTimbre', 'mentalHealth', 'diseases',
    'weapon', 'abilities', 'languages', 'relationship'
];
var CC_EDIT_NSFW_KEYS = [
    'penisLengthErect', 'penisLengthFlaccid', 'penisGirthErect', 'penisGirthFlaccid',
    'scrotumSize', 'ejaculationVolume',
    'sizeTier', 'semenVolumeMax', 'ejaculationForce', 'libido', 'stamina', 'recoveryTime',
    'lactation', 'milkVolume', 'mutation', 'instinctControl', 'extraGenitals'
];
var CC_EDIT_CARD_KEYS = [
    'description', 'personality', 'scenario', 'firstMessage', 'mesExample'
];

/* Select fields → valid options (single source of truth). */
var CC_EDIT_SELECTS = CC_CHAR_SELECTS;

/* Human-readable label for a field key (reuses the T() table). */
function llmEditLabel(key) {
    if (CC_LOC_LABELS[key]) return CC_LOC_LABELS[key];
    var exceptions = { personality: 'personalityLabel', abilities: 'abilitiesLabel' };
    var tk = exceptions[key] || key;
    var v = T(tk);
    return v !== tk ? v : key;
}

/* Which keys are editable given the chosen scope. */
/* Every field a location or narrator card actually has, read off the SAME
   registry the tabs are built from. Hardcoding a second list here is how the
   editor would quietly stop seeing a field the moment one was added. */
function ccEditTypeFieldKeys() {
    var map = ccTypeSections(), keys = [];
    for (var sid in map) {
        if (!map.hasOwnProperty(sid)) continue;
        keys = keys.concat(map[sid]);
    }
    return keys;
}

function llmEditKeysForScope(scope) {
    var keys = [];
    /* A location has no height, no temperament and no outfits; a character has
       no architecture. The "attributes" of a card are whatever ITS type calls
       attributes — the old list was the character's, which is why Edit could
       not see a single location field. */
    if (ccIsLoc() || ccIsNar()) {
        if (scope === 'all' || scope === 'attrs') keys = keys.concat(ccEditTypeFieldKeys());
        if (scope === 'all' || scope === 'card') {
            keys = keys.concat(CC_EDIT_CARD_KEYS);
            keys.push('altGreetings');
        }
        return keys;
    }
    if (scope === 'all' || scope === 'attrs') {
        keys = keys.concat(CC_EDIT_ATTR_KEYS);
        if (ccSettings.showNSFW) keys = keys.concat(CC_EDIT_NSFW_KEYS);
    }
    if (scope === 'all' || scope === 'card') {
        keys = keys.concat(CC_EDIT_CARD_KEYS);
        keys.push('altGreetings');
    }
    if (scope === 'all') keys.push('outfits');
    return keys;
}

/* Serialize the current card (only allowed keys, skip empties). */
function llmEditCollectCard(scope) {
    var keys = llmEditKeysForScope(scope);
    var card = {};
    for (var i = 0; i < keys.length; i++) {
        var k = keys[i];
        var v = ccData[k];
        if (k === 'altGreetings') { if (v && v.length) card[k] = v; continue; }
        if (k === 'outfits') { if (v && v.length) card[k] = v; continue; }
        if (v && String(v).trim()) card[k] = v;
    }
    return card;
}

function llmEditLockedList(keys) {
    var locked = [];
    for (var i = 0; i < keys.length; i++) {
        var k = keys[i];
        if (isLocked(k)) { locked.push(k); continue; }
        var sec = (typeof SECTION_MAP !== 'undefined') ? SECTION_MAP[k] : null;
        if (sec && isSectionLocked(sec)) locked.push(k);
    }
    return locked;
}

/* Ask the LLM for edits. Returns { key: newValue } for changed fields only. */
async function llmEditRun(instruction, scope) {
    if (!genQuiet) throw new Error(T('noLLM'));
    var keys = llmEditKeysForScope(scope);
    var card = llmEditCollectCard(scope);
    if (!Object.keys(card).length) throw new Error(T('llmEditEmptyCard'));

    var locked = llmEditLockedList(keys);
    var lockedBlock = locked.length
        ? '\nLOCKED FIELDS (you must NEVER change these): ' + locked.join(', ') + '\n'
        : '';

    var selectBlock = '';
    for (var sk in CC_EDIT_SELECTS) {
        if (!CC_EDIT_SELECTS.hasOwnProperty(sk)) continue;
        if (keys.indexOf(sk) === -1) continue;
        selectBlock += '- ' + sk + ': ' + CC_EDIT_SELECTS[sk].join(', ') + '\n';
    }

    /* What KIND of card it is, said plainly: "character card editing assistant"
       over a tavern's fields is an instruction to look for a person, and the
       model answered accordingly. */
    var noun = ccIsLoc() ? 'location' : (ccIsNar() ? 'narrator' : 'character');
    var extra = '';
    if (ccIsLoc()) {
        extra = '\nThis card describes a PLACE, not a person. Its fields are about architecture, ' +
            'atmosphere, who is found there and what happens there. Never write about it as if it were a character.\n';
        /* The drawn geometry is a fact about the place the model would
           otherwise contradict — "cramped" over a drawn 96 m² hall. Which of
           the two is read is the card's own answer, not this call site's. */
        if (ccGeomMode(ccData) === 'dollhouse') {
            var dst = ccDhStats(ccDhNormalize(ccData.locDollhouse));
            if (dst) {
                extra += 'A section of the whole building has been drawn for it: ' +
                    dst.cells + (dst.cells === 1 ? ' room' : ' rooms') + ' over ' + dst.floors +
                    (dst.floors === 1 ? ' storey' : ' storeys') + ', ' + dst.width + ' m wide and ' +
                    dst.height + ' m tall. Do not contradict it.\n';
            }
        }
        var st = ccGeomMode(ccData) === 'dollhouse' ? null : ccBpStats(ccBpNormalize(ccData.locBlueprint));
        if (st) {
            extra += 'A floor plan has been drawn for it: ' + st.rooms + (st.rooms === 1 ? ' room' : ' rooms') +
                ' over ' + st.floors + (st.floors === 1 ? ' floor' : ' floors') + ', ' + st.area + ' m² in all' +
                (st.stairs ? ', joined by ' + st.stairs + (st.stairs === 1 ? ' flight' : ' flights') : '') +
                '. Do not contradict it.\n';
        }
    } else if (ccIsNar()) {
        extra = '\nThis card describes a NARRATOR — a storytelling voice, not a person in the story.\n';
    }

    var prompt =
        '[OOC: You are a ' + noun + ' card editing assistant. Below is the current ' + noun + ' card ' +
        'as a JSON object, followed by the user\'s edit instruction.\n' + extra + '\n' +
        'CURRENT CARD:\n' + JSON.stringify(card, null, 1) + '\n' +
        lockedBlock +
        '\nEDIT INSTRUCTION:\n"' + instruction + '"\n\n' +
        'Apply ONLY what the instruction asks for. Rules:\n' +
        '1. Respond with ONLY a JSON object containing the fields you changed, with their COMPLETE new values.\n' +
        '2. Use exactly the same keys as in CURRENT CARD. Do NOT include unchanged fields.\n' +
        '3. If the instruction affects a field not present in CURRENT CARD but listed here, you may add it: ' + keys.join(', ') + '\n' +
        '4. For "altGreetings" (array of strings) and "outfits" (array of objects) return the FULL updated array.\n' +
        '5. Preserve the original language, tone and formatting of the card text. Preserve {{user}} and {{char}} macros as-is.\n' +
        '6. When editing long text fields, keep everything that the instruction does not touch — change only what is asked.\n' +
        (selectBlock ? '7. These fields accept ONLY one of the listed values:\n' + selectBlock : '') +
        'If the instruction changes nothing, respond with {}.\n' +
        'ONLY valid JSON, no commentary!]';

    var raw = await ccGenQuiet(prompt);
    var data = parseJSON(raw);
    if (!data) throw new Error('Failed to parse LLM response.');

    /* Sanitize: keep only allowed keys, drop locked, validate selects, drop no-ops. */
    var changes = {};
    for (var k in data) {
        if (!data.hasOwnProperty(k)) continue;
        if (keys.indexOf(k) === -1) continue;
        if (locked.indexOf(k) !== -1) continue;
        var val = data[k];
        if (k === 'altGreetings') {
            if (!Array.isArray(val)) continue;
            val = val.map(function (s) { return String(s); });
            if (JSON.stringify(val) === JSON.stringify(ccData.altGreetings || [])) continue;
        } else if (k === 'outfits') {
            if (!Array.isArray(val)) continue;
            if (JSON.stringify(val) === JSON.stringify(ccData.outfits || [])) continue;
        } else {
            if (val === null || val === undefined) continue;
            val = String(val);
            if (CC_EDIT_SELECTS[k]) val = matchSelectOption(val, CC_EDIT_SELECTS[k]);
            if (val === (ccData[k] || '')) continue;
        }
        changes[k] = val;
    }
    return changes;
}

/* ── Modal UI ── */

function llmEditPreviewValue(v) {
    var s;
    if (Array.isArray(v)) {
        if (!v.length) return '<i>(empty)</i>';
        if (typeof v[0] === 'object') s = v.map(function (o) { return o && o.name ? o.name : '?'; }).join(', ');
        else s = v.join('\n───\n');
    } else s = String(v || '');
    if (!s.trim()) return '<i>(empty)</i>';
    return esc(s);
}

