    $o.on('click','#cc-ds-polish',async function(){ if(ccBusy||!ccData.dsGallery.length) return; ccBusy=true; var $b=$(this).html('<i class="fa-solid fa-circle-notch fa-spin"></i> Rewrite');
        try{ ccData.dsCaptionMode='nl'; $('.cc-ds-mode-btn').removeClass('active'); $('.cc-ds-mode-btn[data-mode="nl"]').addClass('active'); await dsPolishCaptionsLLM(); dsRenderGrid(); }
        catch(e){ showStatus(e.message,'error'); } ccBusy=false; $b.html('<i class="fa-solid fa-feather"></i> Rewrite'); });

